import { concatBytes } from '../bytes.mjs';
import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;

export function hmacSha1(key, message) {
  const normalizedKey = key.length > BLOCK_SIZE ? sha1(key) : key;
  const keyBlock = new Uint8Array(BLOCK_SIZE);
  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  keyBlock.set(normalizedKey.subarray(0, BLOCK_SIZE));

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    const value = keyBlock[index];
    innerPad[index] = value ^ 0x36;
    outerPad[index] = value ^ 0x5c;
  }

  const innerHash = sha1(concatBytes(innerPad, message));
  return sha1(concatBytes(outerPad, innerHash));
}

